import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(-1)
        return
    max_val = int(data[1])
    for i in range(2, n + 1):
        val = int(data[i])
        if val > max_val:
            max_val = val
    print(max_val)

if __name__ == "__main__":
    main()
